// isVisible reports whether a proto element carrying the given VisibilityRule
// should be included in generated output.
//
// A nil rule means the element has no `google.api.VisibilityRule` annotation
// and is therefore always visible. When a rule is present, its restriction is
// split on commas and the element is visible if any trimmed label overlaps the
// registry's configured visibility_restriction_selectors. If no label matches
// — including the common case where no selectors are configured at all — the
// element is hidden.
func isVisible(r *visibility.VisibilityRule, reg *descriptor.Registry) bool {
	if r == nil {
		return true
	}

	selectors := reg.GetVisibilityRestrictionSelectors()
	for _, restriction := range strings.Split(r.GetRestriction(), ",") {
		if selectors[strings.TrimSpace(restriction)] {
			return true
		}
	}
	return false
}

// fieldVisibility extracts the google.api.field_visibility VisibilityRule from
// a field's options, or nil if the field carries no such annotation.
func fieldVisibility(fd *descriptor.Field) *visibility.VisibilityRule {
	if fd.Options == nil {
