	if !proto.HasExtension(fd.Options, visibility.E_FieldVisibility) {
		return nil
	}
	rule, ok := proto.GetExtension(fd.Options, visibility.E_FieldVisibility).(*visibility.VisibilityRule)
	if !ok {
		return nil
	}
	return rule
}

